ok_all = True
for rel, pairs in R.items():
    p = D + rel
    s = io.open(p, encoding="utf-8").read()
    fails = []
    for i, (old, new) in enumerate(pairs):
        c = s.count(old)
        if c != 1:
            fails.append((i, c, old[:90]))
        else:
            s = s.replace(old, new)
    if fails:
        ok_all = False
        print("FAIL", rel)
        for f in fails: print("   #%d count=%d :: %s" % f)
    else:
        io.open(p, "w", encoding="utf-8").write(s)
        print("OK  ", rel, "(%d replacements)" % len(pairs))
sys.exit(0 if ok_all else 1)
